<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { Icon } from '@iconify/vue'
import { usePptStore } from '@/stores/pptStore'
import { pptApi } from '@/api/ppt'
import { newPptElement, type PptDeck, type PptElement, type PptScope, type PptSlide } from '@/types/domain'
import { pptPhaseLabel, pptElementLabel, pptLayoutLabel } from '@/utils/displayLabels'
import PptCanvas from '@/components/ppt/PptCanvas.vue'
import PptProperties from '@/components/ppt/PptProperties.vue'
import PptSlideProperties from '@/components/ppt/PptSlideProperties.vue'
import PptPlanEditor from '@/components/ppt/PptPlanEditor.vue'
import PptChat from '@/components/ppt/PptChat.vue'
import PptSources from '@/components/ppt/PptSources.vue'
import PptHistory from '@/components/ppt/PptHistory.vue'
import PptProgress from '@/components/ppt/PptProgress.vue'
import { usePptPanels } from '@/components/ppt/usePptPanels'
import '@/components/ppt/ppt.css'
const route = useRoute(), store = usePptStore(), panels = usePptPanels()
const useAgent = ref(true)
const mode = ref<'plan' | 'canvas' | 'history'>('plan'), leftTab = ref<'slides' | 'sources'>('slides'), rightTab = ref<'chat' | 'properties'>('chat')
const slideId = ref(''), elementId = ref(''), scopeKind = ref<PptScope['kind']>('DOCUMENT'), leftOpen = ref(false), rightOpen = ref(false), planDirty = ref(false), propertyDirty = ref(false)
const historical = ref<{ revision: number; deck: PptDeck } | null>(null), localError = ref(''), layout = ref('title_content')
const scene = computed(() => historical.value?.deck || store.deck), revision = computed(() => historical.value?.revision ?? store.document?.revision ?? 0)
const slide = computed(() => scene.value?.slides.find(value => value.id === slideId.value) || scene.value?.slides[0] || null)
const element = computed(() => slide.value?.elements.find(value => value.id === elementId.value) || null)
const editable = computed(() => store.editable && !historical.value)
const scope = computed<PptScope>(() => ({ kind: scopeKind.value, ...(scopeKind.value === 'SECTION' ? { section: slide.value?.section } : {}), ...(['SLIDE', 'ELEMENT'].includes(scopeKind.value) ? { slideId: slide.value?.id } : {}), ...(scopeKind.value === 'ELEMENT' ? { elementId: element.value?.id } : {}) }))
const validScope = computed(() => scopeKind.value === 'DOCUMENT' || (scopeKind.value === 'SECTION' ? !!slide.value?.section : scopeKind.value === 'SLIDE' ? !!slide.value : !!element.value))
const scopeLabel = computed(() => scopeKind.value === 'DOCUMENT' ? '全部章节与页面' : scopeKind.value === 'SECTION' ? slide.value?.section || '请先选择有章节的页面' : scopeKind.value === 'SLIDE' ? slide.value?.title || '请先选择页面' : element.value ? `${slide.value?.title} · ${pptElementLabel(element.value.type)}` : '请先选择对象')
const preview = computed(() => { const candidates = store.jobs.filter(job => job.kind === 'PREVIEW' && (!historical.value || job.revision === historical.value.revision)).flatMap(job => job.artifacts.filter(artifact => artifact.slideId === slide.value?.id && artifact.mediaType === 'image/png').map(artifact => ({ artifact, revision: job.revision, createdAt: job.createdAt }))).sort((a, b) => b.revision - a.revision || b.createdAt.localeCompare(a.createdAt)); return candidates[0] })
let ticket = 0
watch(() => route.params.id, async value => { const current = ++ticket; historical.value = null; localError.value = ''; elementId.value = ''; scopeKind.value = 'DOCUMENT'; rightTab.value = 'chat'; planDirty.value = false; propertyDirty.value = false; await store.load(String(value)); if (current !== ticket) return; try { slideId.value = sessionStorage.getItem(`loopper.ppt.slide.${value}`) || '' } catch { slideId.value = '' } mode.value = ['PRODUCING', 'REVIEW', 'EXPORTED'].includes(store.document?.phase || '') ? 'canvas' : 'plan' }, { immediate: true })
watch(slideId, value => { if (store.document) try { sessionStorage.setItem(`loopper.ppt.slide.${store.document.id}`, value) } catch { /* Optional position preference. */ } })
const timer = setInterval(() => { if (store.active || store.jobsActive || store.disconnected) void store.refresh() }, 4000)
onBeforeUnmount(() => { ticket++; clearInterval(timer); store.close() })
function selectSlide(id: string) { slideId.value = id; elementId.value = ''; scopeKind.value = 'SLIDE'; leftOpen.value = false; propertyDirty.value = false }
function selectElement(id: string) { elementId.value = id; rightTab.value = id ? 'properties' : rightTab.value; scopeKind.value = id ? 'ELEMENT' : 'SLIDE'; propertyDirty.value = false }
async function patchElement(id: string, patch: Partial<PptElement>, base: number) { if (!slide.value || !editable.value) return; const currentSlide = slide.value.id; if (await store.operations([{ op: 'update_element', slideId: currentSlide, elementId: id, patch }], base)) { await store.createJob('PREVIEW', currentSlide) } }
async function addElement(type: string, assetId?: string) { if (!slide.value || !editable.value) return; const created = newPptElement(type); if (assetId) created.assetId = assetId; if (await store.operations([{ op: 'add_element', slideId: slide.value.id, element: created }])) { elementId.value = created.id; rightTab.value = 'properties'; await store.createJob('PREVIEW', slide.value?.id) } }
async function removeElement(id: string) { if (!slide.value || !window.confirm('删除这个对象？历史版本仍会保留。')) return; if (await store.operations([{ op: 'remove_element', slideId: slide.value.id, elementId: id }])) { elementId.value = ''; await store.createJob('PREVIEW', slide.value?.id) } }
async function addSlide() { const id = crypto.randomUUID(); if (await store.operations([{ op: 'create_slide', slide: { id, title: `第 ${(store.deck?.slides.length || 0) + 1} 页`, section: '', notes: '', locked: false, elements: [] } }])) { slideId.value = id; mode.value = 'canvas' } }
async function slideAction(action: 'duplicate_slide' | 'delete_slide' | 'move_slide', index?: number) { if (!slide.value) return; if (action === 'delete_slide' && !window.confirm('删除当前页面？历史版本仍会保留。')) return; await store.operations([{ op: action, slideId: slide.value.id, index }]); if (!scene.value?.slides.some(item => item.id === slideId.value)) slideId.value = scene.value?.slides[0]?.id || '' }
async function confirmDirection() { if (store.document?.phase === 'BRIEFING' && !await store.action('finish-planning')) return; if (await store.action('confirm-direction')) mode.value = 'plan' }
async function fillPlannedPages() { const missing = store.plan.slides.filter(planned => !store.deck?.slides.some(existing => existing.id === planned.id)); if (!missing.length) return; if (await store.operations(missing.map(planned => ({ op: 'create_slide', slide: { id: planned.id, title: planned.title, section: planned.section, notes: planned.notes, locked: false, elements: [] } })))) slideId.value = missing[0]!.id }
async function startProduction() { if (await store.action('start-production', { useAgent: useAgent.value })) { mode.value = 'canvas'; if (!useAgent.value) await fillPlannedPages() } }
async function patchSlide(id: string, patch: Partial<PptSlide>, base: number) { await store.operations([{ op: 'update_slide', slideId: id, patch }], base) }
async function theme(value: string) { if (await store.operations([{ op: 'apply_theme', theme: value }])) await store.createJob('PREVIEW') }
async function inspectRevision(value: number) { if (!store.document) return; const id = store.document.id; try { const deck = await pptApi.deck(id, value); if (id === store.document?.id) { historical.value = { revision: value, deck }; mode.value = 'canvas'; elementId.value = '' } } catch { localError.value = '历史版本暂时无法读取，请重试' } }
async function restoreRevision(value: number) { if (!window.confirm(`将版本 ${value} 恢复为一个新版本？当前内容会保留在历史记录中。`)) return; if (await store.action('restore', { targetRevision: value })) { historical.value = null; mode.value = 'canvas' } }
async function archive() { if (!store.document) return; if (!store.document.archived && !window.confirm('归档这份作品？可以从作品列表恢复。')) return; await store.action('archive', { archived: !store.document.archived }) }
async function reopen() { if (!window.confirm('重新打开制作需求？已有页面和导出将保留。')) return; if (await store.action('reopen')) mode.value = 'plan' }
</script>
<template>
  <main id="main-content" class="ppt-page ppt-studio" aria-label="PPT 工作台" @keydown.esc="leftOpen = false; rightOpen = false">
    <header class="ppt-topbar"><div><RouterLink to="/ppt" class="ppt-back">← 作品列表</RouterLink><h1>{{ store.document?.title || 'PPT 工作室' }}</h1><p v-if="store.document">{{ pptPhaseLabel(store.document.phase) }} · 版本 {{ store.document.revision }}<span v-if="store.document.model"> · {{ store.document.model }}</span><span v-if="store.document.archived"> · 已归档</span><span v-if="store.busy"> · 正在保存</span><span v-else-if="planDirty || propertyDirty"> · 有未保存修改</span></p></div><div class="ppt-top-actions"><button :disabled="store.busy || !store.document" @click="mode = 'history'">版本与导出</button><button :disabled="!editable || !scene?.slides.length || !store.capabilities?.renderingAvailable" @click="store.createJob('PREVIEW')">生成预览</button><button v-if="store.document?.phase === 'PRODUCING'" :disabled="!editable || store.active" @click="store.action('finish-production')">检查并完成制作</button><button class="ppt-primary" :disabled="!editable || !scene?.slides.length || !store.capabilities?.renderingAvailable || store.active || !['REVIEW', 'EXPORTED'].includes(store.document?.phase || '')" @click="store.createJob('EXPORT')">导出 PPTX</button><button :disabled="store.busy || store.active || !store.document" @click="archive">{{ store.document?.archived ? '恢复作品' : '归档' }}</button></div></header>
    <p v-if="store.error || localError" role="alert" class="ppt-notice ppt-page-notice">{{ store.error || localError }}<button :disabled="store.busy" @click="localError = ''; store.error = ''; store.refresh()">重新核对状态</button><button v-if="store.pending" :disabled="store.busy" @click="store.retryPending">重试原操作</button></p><p v-if="store.disconnected" role="status" class="ppt-notice ppt-page-notice">实时连接已断开，正在读取最新状态；不会重复发送请求。</p>
    <p v-if="store.capabilities && !store.capabilities.renderingAvailable" role="alert" class="ppt-notice ppt-page-notice">{{ store.capabilities.renderingMessage || '当前环境无法渲染，请检查字体与运行环境后重试' }}</p><div v-if="store.loading && !store.document" class="ppt-empty">正在读取作品…</div>
    <template v-if="store.document"><PptProgress v-if="mode !== 'history'" :jobs="store.jobs" :revision="store.document.revision" :busy="store.busy" @history="mode = 'history'" @retry="store.retryJob" /><div class="ppt-workspace-controls"><button @click="leftOpen = !leftOpen; rightOpen = false">资料与页面</button><nav class="ppt-tabs" aria-label="工作区"><button :class="{ active: mode === 'plan' }" @click="mode = 'plan'">制作方案</button><button :class="{ active: mode === 'canvas' }" @click="mode = 'canvas'">页面制作</button></nav><button @click="rightOpen = !rightOpen; leftOpen = false">助手与属性</button></div>
      <div class="ppt-workspace" :class="{ 'left-open': leftOpen, 'right-open': rightOpen }" :style="{ '--ppt-left-width': `${panels.leftWidth.value}px`, '--ppt-right-width': `${panels.rightWidth.value}px` }">
        <aside class="ppt-left-panel"><nav class="ppt-tabs"><button :class="{ active: leftTab === 'slides' }" @click="leftTab = 'slides'">页面</button><button :class="{ active: leftTab === 'sources' }" @click="leftTab = 'sources'">资料</button><button class="ppt-panel-close" @click="leftOpen = false">收起</button></nav><PptSources v-if="leftTab === 'sources'" @insert="addElement('image', $event)" /><div v-else class="ppt-slide-list"><button class="ppt-add-slide" :disabled="!editable" @click="addSlide"><Icon icon="lucide:plus" />新建页面</button><button v-for="(item, index) in scene?.slides || []" :key="item.id" :class="['ppt-slide-card', { selected: slide?.id === item.id }]" @click="selectSlide(item.id); mode = 'canvas'"><span>{{ index + 1 }}</span><div><strong>{{ item.title || '未命名页面' }}</strong><small>{{ item.section }}{{ item.locked ? ' · 已锁定' : '' }}</small></div></button><p v-if="!scene?.slides.length" class="ppt-empty">确认逐页设计后，助手将制作页面。</p></div></aside>
        <div class="ppt-separator ppt-separator-left" role="separator" aria-label="调整页面栏宽度" aria-orientation="vertical" tabindex="0" :aria-valuenow="panels.leftWidth.value" :aria-valuemin="180" :aria-valuemax="360" @pointerdown="panels.start($event, 'left')" @keydown="panels.keyboard($event, 'left')" />
        <section class="ppt-center-panel"><template v-if="mode === 'plan'"><div class="ppt-stage-actions"><button v-if="['BRIEFING', 'DIRECTION'].includes(store.document.phase)" class="ppt-primary" :disabled="!editable || store.active || planDirty || !store.plan.selectedDirectionId" @click="confirmDirection">确认整体方向</button><label v-if="store.document.phase === 'DESIGN'" class="ppt-check"><input v-model="useAgent" type="checkbox" :disabled="store.busy || store.active" />由 PPT 助手制作</label><button v-if="store.document.phase === 'DESIGN'" class="ppt-primary" :disabled="!editable || store.active || planDirty || !store.plan.slides.length" @click="startProduction">确认设计并开始制作</button><button v-if="['DESIGN', 'PRODUCING', 'REVIEW', 'EXPORTED'].includes(store.document.phase)" :disabled="!editable || store.active" @click="reopen">重新打开需求</button></div><PptPlanEditor :plan="store.plan" :document-id="store.document.id" :sources="store.sources" :direction-frozen="store.document.phase === 'DESIGN'" :revision="store.document.revision" :disabled="!editable || !['BRIEFING', 'DIRECTION', 'DESIGN'].includes(store.document.phase)" :capabilities="store.capabilities" @save="store.savePlan" @dirty="planDirty = $event" /></template>
          <PptHistory v-else-if="mode === 'history'" @view="inspectRevision" @restore="restoreRevision" />
          <template v-else><p v-if="historical" class="ppt-notice">正在查看历史版本 {{ historical.revision }}<button @click="historical = null">返回当前草稿</button></p><button v-if="store.document.phase === 'PRODUCING' && store.plan.slides.some(planned => !store.deck?.slides.some(existing => existing.id === planned.id))" :disabled="!editable || store.active" @click="fillPlannedPages">补齐设计页面</button><div v-if="slide && scene" class="ppt-slide-editor"><header class="ppt-section-heading"><h2>{{ slide.title || '未命名页面' }}</h2><button :disabled="!editable" @click="store.operations([{ op: 'update_slide', slideId: slide.id, patch: { locked: !slide.locked } }])">{{ slide.locked ? '解锁页面' : '锁定页面' }}</button></header><div class="ppt-editor-toolbar"><button v-for="type in ['text', 'shape', 'line', 'table', 'chart']" :key="type" :disabled="!editable || slide.locked" @click="addElement(type)">添加{{ pptElementLabel(type) }}</button><button :disabled="!editable || slide.locked" @click="leftTab = 'sources'; leftOpen = true">插入图片</button><select v-model="layout" aria-label="页面版式"><option v-for="value in store.capabilities?.layouts || []" :key="value" :value="value">{{ pptLayoutLabel(value) }}</option></select><button :disabled="!editable || slide.locked" @click="store.operations([{ op: 'apply_layout', slideId: slide.id, layout }])">应用版式</button></div><label class="ppt-theme-choice">演示主题<select :value="scene.theme" :disabled="!editable" @change="theme(($event.target as HTMLSelectElement).value)"><option v-for="item in store.capabilities?.themes || []" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><PptCanvas :deck="scene" :slide="slide" :selected="elementId" :revision="revision" :disabled="!editable" :preview="preview ? pptApi.artifactUrl(store.document.id, preview.artifact.id) : undefined" :preview-revision="preview?.revision" @select="selectElement" @patch="patchElement" @remove="removeElement" /><div class="ppt-editor-toolbar"><button :disabled="!editable" @click="slideAction('duplicate_slide')">复制页面</button><button :disabled="!editable || scene.slides.findIndex(item => item.id === slide?.id) === 0" @click="slideAction('move_slide', Math.max(0, scene.slides.findIndex(item => item.id === slide?.id) - 1))">上移</button><button :disabled="!editable || scene.slides.findIndex(item => item.id === slide?.id) === scene.slides.length - 1" @click="slideAction('move_slide', scene.slides.findIndex(item => item.id === slide?.id) + 1)">下移</button><button :disabled="!editable || slide.locked" @click="slideAction('delete_slide')">删除页面</button><button :disabled="!editable || !element || element.locked || slide.locked" @click="element && store.operations([{ op: 'move_element', slideId: slide.id, elementId: element.id, index: slide.elements.length - 1 }])">对象置顶</button><button :disabled="!editable || !element || element.locked || slide.locked" @click="element && store.operations([{ op: 'move_element', slideId: slide.id, elementId: element.id, index: 0 }])">对象置底</button><button :disabled="store.busy" @click="store.check">检查页面</button><button :disabled="!editable" @click="store.createJob('PREVIEW', slide.id)">更新当前页预览</button></div><section v-if="store.checkedRevision === store.document.revision" class="ppt-checks"><p v-if="!store.issues.length" class="ppt-muted">该版本未发现布局问题。</p><h3>布局检查</h3><p v-for="(issue, index) in store.issues" :key="index" class="ppt-notice"><button @click="selectSlide(issue.slideId); selectElement(issue.elementId)">定位对象</button>{{ issue.message }}</p></section></div><div v-else class="ppt-empty"><p>还没有页面，先完成制作方案，或手动添加页面。</p><button :disabled="!editable" @click="addSlide">新建页面</button></div></template>
        </section>
        <div class="ppt-separator ppt-separator-right" role="separator" aria-label="调整助手栏宽度" aria-orientation="vertical" tabindex="0" :aria-valuenow="panels.rightWidth.value" :aria-valuemin="280" :aria-valuemax="520" @pointerdown="panels.start($event, 'right')" @keydown="panels.keyboard($event, 'right')" />
        <aside class="ppt-right-panel"><nav class="ppt-tabs"><button :class="{ active: rightTab === 'chat' }" @click="rightTab = 'chat'">PPT 助手</button><button :class="{ active: rightTab === 'properties' }" @click="rightTab = 'properties'">对象属性</button><button class="ppt-panel-close" @click="rightOpen = false">收起</button></nav><PptChat v-show="rightTab === 'chat'" :scope="scope" :scope-label="scopeLabel" :disabled="store.document.archived || !!historical || !validScope" @change-scope="scopeKind = $event" /><PptSlideProperties v-if="rightTab === 'properties' && !element && slide" :slide="slide" :document-id="store.document.id" :revision="revision" :disabled="!editable" @save="patchSlide" @dirty="propertyDirty = $event" /><PptProperties v-else-if="rightTab === 'properties'" :element="element" :document-id="store.document.id" :revision="revision" :capabilities="store.capabilities" :disabled="!editable" :slide-locked="slide?.locked" @save="patchElement" @remove="removeElement" @dirty="propertyDirty = $event" /></aside>
      </div>
    </template>
  </main>
</template>
